previewCss:
.darma-loader-darma-b17-milk-churn { --accent: var(--loader-color, #78716c); --accent-2: var(--loader-secondary-color, #fef9c3); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b17-milk-churn .darma-loader-darma-b17-milk-churn__pot { position: absolute; left: 20%; right: 20%; bottom: 4%; height: 56%; border-radius: 8px 8px 22% 22%; background: linear-gradient(90deg, color-mix(in srgb, #fff 22%, var(--accent)), var(--accent) 60%, color-mix(in srgb, #000 22%, var(--accent))); }
.darma-loader-darma-b17-milk-churn .darma-loader-darma-b17-milk-churn__cream { position: absolute; left: 24%; right: 24%; bottom: 8%; height: 32%; border-radius: 4px 4px 20% 20%; background: var(--accent-2); animation: darma-loader-darma-b17-milk-churn-churn-slosh calc(var(--loader-speed, 1s) * .9) ease-in-out infinite; }
.darma-loader-darma-b17-milk-churn .darma-loader-darma-b17-milk-churn__plunger { position: absolute; left: 46%; top: 2%; width: 8%; height: 62%; border-radius: 3px; background: linear-gradient(#e2e8f0, #94a3b8); animation: darma-loader-darma-b17-milk-churn-churn-push calc(var(--loader-speed, 1s) * .9) ease-in-out infinite; }
.darma-loader-darma-b17-milk-churn .darma-loader-darma-b17-milk-churn__plunger::after { content: ''; position: absolute; left: -110%; top: 88%; width: 320%; height: 10%; border-radius: 3px; background: #94a3b8; }
.darma-loader-darma-b17-milk-churn i { position: absolute; width: 7%; height: 7%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b17-milk-churn-churn-splash calc(var(--loader-speed, 1s) * .9) ease-out infinite; }
.darma-loader-darma-b17-milk-churn i:nth-of-type(1) { left: 26%; bottom: 40%; --dx: -60%; }
.darma-loader-darma-b17-milk-churn i:nth-of-type(2) { right: 26%; bottom: 40%; --dx: 60%; animation-delay: calc(var(--loader-speed, 1s) * .45); }
@keyframes darma-loader-darma-b17-milk-churn-churn-push { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(16%); } }
@keyframes darma-loader-darma-b17-milk-churn-churn-slosh { 0%, 100% { transform: scaleY(1) skewX(0deg); } 50% { transform: scaleY(1.08) skewX(3deg); } }
@keyframes darma-loader-darma-b17-milk-churn-churn-splash { 0%, 40% { opacity: 0; transform: translate(0, 0) scale(.5); } 55% { opacity: 1; transform: translate(calc(var(--dx, 0%) * .5), -60%) scale(1); } 100% { opacity: 0; transform: translate(var(--dx, 0%), -10%) scale(.6); } }

